Aquí hay un algoritmo de JavaScript para generar un tablero de Sudoku válido usando recursividad:

function generateSudokuBoard(board) {
  if (board.isFull()) {
    return board;
  }

  let [row, col] = board.getNextEmptyCell();
  let possibleValues = board.getPossibleValues(row, col);

  for (let value of possibleValues) {
    board.setCell(row, col, value);

    let result = generateSudokuBoard(board);
    if (result) {
      return result;
    }
  }

  board.setCell(row, col, 0);
  return null;
}

