Aquí tienes una función en Python que podría ayudarte a detectar las horas del día con mayor número de excedentes eléctricos por mes del año. Asegúrate de adaptarla a tus necesidades específicas.

def detectar_excedentes(registro):
    excedentes_por_mes = {}
    for mes in range(1, 13):
        excedentes_por_mes[mes] = [0] * 24
    for entrada in registro:
        mes = entrada['fecha'].month
        hora = entrada['fecha'].hour
        excedentes_por_mes[mes][hora] += entrada['excedente']
    resultado = {}
    for mes, excedentes in excedentes_por_mes.items():
        max_excedente = max(excedentes)
        horas_max_excedente = [hora for hora, excedente in enumerate(excedentes) if excedente == max_excedente]
        resultado[mes] = horas_max_excedente
    return resultado
